out=Path('docs/issues');out.mkdir(exist_ok=True)
road=['# FinSight AI — 30 days of genuine engineering\n','The MVP is the starting point. These are future tasks, not completed work. Budget roughly 2 focused hours per day; split larger items across sessions rather than rushing. Each day has a ready-to-create GitHub issue below. No remote repository was supplied, so these are issue drafts, not claims that GitHub issues already exist.\n','Open one issue when beginning a task. Implement, verify, explain what changed, then make a meaningful commit. Never backdate or automate activity for a contribution graph.\n']
for i,(title,task,accept,commit,test,learn) in enumerate(items,1):
 body=f'# Day {i:02}: {title}\n\n## Task\n{task}\n\n## Acceptance criteria\n- [ ] {accept}\n- [ ] Document observed limits and assumptions.\n\n## Verification\n{test}\n\n## Suggested commit\n`{commit}`\n\n## Concept learned\n{learn}. Explain the implementation aloud before closing the issue.\n'
 (out/f'day-{i:02}.md').write_text(body)
 road.append(body+'\n---\n')
Path('docs/ROADMAP.md').write_text('\n'.join(road))
Path('docs/issues.json').write_text(json.dumps([{'day':i,'title':f'Day {i:02}: {t[0]}','body_file':f'docs/issues/day-{i:02}.md'} for i,t in enumerate(items,1)],indent=2))
